local logger = require("transformer.logger")
local log = logger.new("wireless.radio.acs", 2)
local register = register;

local wireless_radio_acs_ = {
  objectType = {
    name = "rpc.wireless.radio.@.acs.",
    access = "readOnly",
    minEntries = 1,
    maxEntries = 1,
    parameters = {
      scan_report = { 
          access = "readOnly",
          type = "string",
      },
      rescan = { 
          access = "readWrite",
          type = "boolean",
          default = "false", 
      },
    },
  }
}

local uci_helper = mapper("ucihelper")
local ubus = require("ubus")
local conn = ubus.connect()
if not conn then
    error("Failed to connect to ubusd")
end

local function get (mapping, paramname, key)
    local content = {}                                   
    content = conn:call("wireless.radio.acs", "get", { name = key } )
    if content == nil then                                             
        log:error(format("Cannot retrieve acs object %s", key))
    elseif content[key] and content[key][paramname] then  
        return tostring(content[key][paramname])                      
    end                                                                       
    return ""                                                                 
end                                                                           
                                                                              
local set ={
  rescan = function()
	log:error("---->>set rescan")
	os.execute("ubus call wireless.radio.acs rescan")
  end
} 

wireless_radio_acs_.get = get
wireless_radio_acs_.set = set
register(wireless_radio_acs_)

